<?php
namespace Tests\Feature;use App\Models\{Institution,ProjectProfile,Survey,User};use Database\Seeders\RolesAndPermissionsSeeder;use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Support\Facades\Storage;use Tests\TestCase;
class ReportExportTest extends TestCase{use RefreshDatabase;protected function setUp():void{parent::setUp();$this->seed(RolesAndPermissionsSeeder::class);}public function test_analyst_can_create_and_export_report():void{Storage::fake('local');$u=User::factory()->create();$u->assignRole('Analyst');$i=Institution::create(['name'=>'Adekunle Ajasin University, Akungba','slug'=>'aaua']);ProjectProfile::create(['institution_id'=>$i->id,'project_title'=>'Wi-Fi Optimisation','aim'=>'RF heat mapping and load analysis','objectives'=>[],'scope'=>[],'limitations'=>[],'methodology'=>[],'is_active'=>true]);$c=$i->campuses()->create(['name'=>'Akungba Campus','code'=>'AAUA']);$b=$c->buildings()->create(['name'=>'Library','code'=>'LIB']);$f=$b->floors()->create(['name'=>'Ground','code'=>'G','level_number'=>0]);$fp=$f->floorPlans()->create(['uploaded_by'=>$u->id,'original_name'=>'p','file_path'=>'p','mime_type'=>'image/png','file_size'=>1,'version'=>1]);$s=Survey::create(['floor_id'=>$f->id,'floor_plan_id'=>$fp->id,'created_by'=>$u->id,'name'=>'Baseline']);$res=$this->actingAs($u)->postJson('/api/reports',['title'=>'Baseline Report','report_type'=>'survey','survey_id'=>$s->id,'period_start'=>now()->subDay()->toDateString(),'period_end'=>now()->toDateString()])->assertCreated();$id=$res->json('id');$this->get("/reports/$id/csv")->assertOk()->assertHeader('content-type','text/csv; charset=UTF-8')->assertSee('Good-signal coverage is the share')->assertSee('validation');$this->get("/reports/$id/preview")->assertOk()->assertSee('How to read the figures')->assertSee('Good-signal coverage');$this->get("/reports/$id/pdf")->assertOk()->assertHeader('content-type','application/pdf');$this->assertNotNull(\App\Models\ReportExport::where('report_id',$id)->whereNotNull('file_path')->value('file_path'));}}
